#![cfg(feature="follow-defense-schemas")]
//! Prepared model construct/validate/materialize workload; not an end-to-end benchmark.
use dima_rust::schemas::{follow_attack_log,follow_defense_action,follow_hate_raid_source,SchemaDefinition};
use mongodb::bson::{self,DateTime,Document};
#[path="support/sha256.rs"] mod digest;
fn unhex(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
#[test]
#[ignore="requires separately prepared immutable input and release build"]
fn prepared_model_construction_benchmark(){
 use std::{fs,path::PathBuf,time::Instant,io::Write};
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).canonicalize().unwrap();let input=PathBuf::from(std::env::var("FOLLOW_DEFENSE_BENCH_INPUT").unwrap());assert!(input.is_absolute()&&fs::canonicalize(&input).unwrap()==input&&!input.starts_with(root.parent().unwrap()));assert!(fs::symlink_metadata(&input).unwrap().is_file());let original=fs::read(&input).unwrap();let pin=std::env::var("FOLLOW_DEFENSE_BENCH_INPUT_SHA256").unwrap();assert_eq!(digest::sha256_hex(&original),pin);
 let data:serde_json::Value=serde_json::from_slice(&original).unwrap();assert_eq!(data["schema"],1);let hashes=data["hashes"].as_object().unwrap();for (file,hash) in hashes{assert_eq!(digest::sha256_hex(&fs::read(root.join(file)).unwrap()),hash.as_str().unwrap());}
 let sources=[("src/schemas/follow_attack_log.schema.ts","418077f7dae3dbfbea4e800eb1444920de2c202828dbe97b87c3e074cea0b032"),("src/schemas/follow_defense_action.schema.ts","0b56200c8aa2ad0c29668c82da87354517774c2e523e448868daf4c7fafc9cf4"),("src/schemas/follow_hate_raid_source.schema.ts","8b2321fcf3eed917304bd3d2e03bf975b5351a3a37494cbe1e8ad54947c1215e")];for (i,(path,sha)) in sources.iter().enumerate(){assert_eq!(data["sourceHashes"][i],*sha);assert_eq!(digest::sha256_hex(&fs::read(root.join(path)).unwrap()),*sha);}
 let schemas:[&SchemaDefinition;4]=[follow_attack_log::schema(),follow_defense_action::action_schema(),follow_defense_action::control_schema(),follow_hate_raid_source::schema()];let workloads=data["workloads"].as_array().unwrap();assert_eq!(workloads.len(),4);let names=["attack-log","defense-action","durable-control","hate-raid-source"];let scalar_keys=["targetChannelID","_id","_id","targetChannelID"];
 let mut results=Vec::new();for (i,w) in workloads.iter().enumerate(){assert_eq!(w["name"],names[i]);assert_eq!(w["passes"],1000);let pool=w["pool"].as_array().unwrap();assert_eq!(pool.len(),32);let mut inputs=Vec::<Document>::new();let mut expected=0u64;
  for case in pool {let input:Document=bson::deserialize_from_slice(&unhex(case["inputHex"].as_str().unwrap())).unwrap();let golden:Document=bson::deserialize_from_slice(&unhex(case["outputHex"].as_str().unwrap())).unwrap();let actual=schemas[i].construct(&input,DateTime::from_millis(1900000000000)).unwrap();assert_eq!(actual,golden);let scalar=case["scalar"].as_u64().unwrap();assert_eq!(actual.get_str(scalar_keys[i]).unwrap().len() as u64,scalar);expected+=scalar;inputs.push(input);}
  let run=|passes:usize|->u64{let mut sum=0;for _ in 0..passes{for input in &inputs{let output=schemas[i].construct(std::hint::black_box(input),DateTime::from_millis(1900000000000)).unwrap();sum+=std::hint::black_box(output.get_str(scalar_keys[i]).unwrap().len() as u64);}}sum};assert_eq!(run(20),expected*20);let mut samples=Vec::new();for _ in 0..7{let start=Instant::now();let checksum=run(1000);let elapsed=start.elapsed().as_nanos() as u64;assert_eq!(checksum,expected*1000);samples.push(serde_json::json!({"elapsedNs":elapsed,"nsPerOp":elapsed as f64/32000.0,"checksum":checksum}));}results.push(serde_json::json!({"name":names[i],"samples":samples}));
 }
 assert_eq!(fs::read(&input).unwrap(),original);assert_eq!(digest::sha256_hex(&original),pin);let output=PathBuf::from(std::env::var("FOLLOW_DEFENSE_BENCH_OUTPUT").unwrap());assert!(output.is_absolute()&&!output.starts_with(root.parent().unwrap()));let parent=output.parent().unwrap();assert_eq!(fs::canonicalize(parent).unwrap(),parent);let mut file=fs::OpenOptions::new().create_new(true).write(true).open(output).unwrap();writeln!(file,"{}",serde_json::json!({"schema":1,"inputSha":pin,"results":results})).unwrap();
}
